// sw-custom.js — imported by the Workbox SW generated by next-pwa.
// Handles Firebase Cloud Messaging (background) AND Web Push/VAPID messages.
// This is the single service worker — no separate firebase-messaging-sw.js needed.

let firebaseInitialised = false;

// ── Receive Firebase config from the client app ───────────────────────────────
// The client calls postMessage({ type: "FCM_CONFIG", config: {...} }) after
// the SW is ready. We use that to initialise Firebase Messaging in SW context.
self.addEventListener("message", (event) => {
  if (event.data?.type !== "FCM_CONFIG") return;
  if (firebaseInitialised) return;

  const config = event.data.config;
  if (!config?.projectId) return;

  try {
    importScripts("https://www.gstatic.com/firebasejs/10.12.2/firebase-app-compat.js");
    importScripts("https://www.gstatic.com/firebasejs/10.12.2/firebase-messaging-compat.js");

    if (!self.firebase.apps.length) {
      self.firebase.initializeApp(config);
    }

    const messaging = self.firebase.messaging();

    // Background / closed-app messages (FCM)
    messaging.onBackgroundMessage((payload) => {
      const n    = payload.notification ?? {};
      const d    = payload.data ?? {};
      const title = n.title ?? d.title ?? "Tiffin Tracker 🍱";
      const body  = n.body  ?? d.body  ?? "You have a new notification.";
      const url   = d.url   ?? "/";

      self.registration.showNotification(title, {
        body,
        icon:     "/icons/icon-192x192.png",
        badge:    "/icons/icon-72x72.png",
        tag:      "tiffin-fcm",
        renotify: true,
        data:     { url },
      });
    });

    firebaseInitialised = true;
  } catch (e) {
    console.log("[SW] Firebase init failed:", e.message);
  }
});

// ── Web Push / VAPID fallback ─────────────────────────────────────────────────
// Handles non-FCM push events (VAPID). FCM messages are intercepted by
// firebase/messaging compat SDK above and will NOT re-trigger this listener.
self.addEventListener("push", (event) => {
  if (!event.data) return;

  let data = {};
  try { data = event.data.json(); } catch { return; }

  const title = data.title ?? "Tiffin Tracker 🍱";
  const body  = data.body  ?? "Time to record your meal!";
  const url   = data.url   ?? "/";

  event.waitUntil(
    self.registration.showNotification(title, {
      body,
      icon:     "/icons/icon-192x192.png",
      badge:    "/icons/icon-72x72.png",
      tag:      "tiffin-reminder",
      renotify: true,
      data:     { url },
    })
  );
});

// ── Notification click ────────────────────────────────────────────────────────
// Shared handler for both FCM and VAPID notifications.
self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const url = event.notification.data?.url ?? "/";

  event.waitUntil(
    clients
      .matchAll({ type: "window", includeUncontrolled: true })
      .then((clientList) => {
        for (const client of clientList) {
          if (client.url.includes(self.location.origin) && "focus" in client) {
            client.navigate(url);
            return client.focus();
          }
        }
        if (clients.openWindow) return clients.openWindow(url);
      })
  );
});
